using UnityEngine;
namespace InventixGames.Core { [DefaultExecutionOrder(-10000)] public class GameBootstrap : MonoBehaviour { [SerializeField] private string firstSceneToLoad = "MainMenu"; [SerializeField] private bool dontDestroyOnLoad = true; private void Awake() { if (dontDestroyOnLoad) DontDestroyOnLoad(gameObject); Application.targetFrameRate = 60; ServiceLocator.Register<ISaveService>(new JsonSaveService()); ServiceLocator.Register<IAudioService>(gameObject.AddComponent<AudioService>()); ServiceLocator.Register<Mission.IMissionService>(gameObject.AddComponent<Mission.MissionManager>()); ServiceLocator.Register<IAICopilotService>(gameObject.AddComponent<ClaudeCopilotService>()); } private void Start() => SceneLoader.LoadSceneAsync(firstSceneToLoad); } }
